import { Component, Element, Host, Prop, State, h } from "@stencil/core";
import { addConstructedStyle } from "../../utils/browser";
import { getCssRulesForSentimentBadge } from "../../utils/sentiments";

/**
 * @since 0.0.10
 * @status statable
 *
 * @description Badges are indicators to draw attention, display statuses or counts. They are placed in close proximity to other elements like icon-buttons or menu-items they are paired with.
 *
 * @slot - The badge's content for non-superscript usage.
 * @slot base - The anchor element for an anchored badge.
 * @slot badge - The badge indicator content for an anchored badge.
 *
 * @part base - The base wrapper
 * @part indicator - The anchored badge indicator
 */

@Component({
	tag: "hbr-badge",
	styleUrl: "badge.scss",
	shadow: true,
})
export class Badge {
	badge!: HTMLElement;
	sheet: CSSStyleSheet = new CSSStyleSheet();
	@Element() host!: HTMLHbrBadgeElement;
	@State() hasBaseSlot = false;
	@State() hasBadgeSlot = false;

	/** The badge's sentiment. */
	@Prop({ reflect: true }) sentiment:
		| "interact"
		| "success"
		| "neutral"
		| "info"
		| "warning"
		| "danger";

	/** Disables the badge. */
	@Prop({ reflect: true }) disabled = false;

	/** Draws a pill-style badge with rounded edges. */
	@Prop({ reflect: true }) pill = false;

	/** Displays the badge inline with the content around it. */
	@Prop({ reflect: true }) inline = false;

	/** Makes the badge pulsate to draw attention. */
	@Prop({ reflect: true }) pulse = false;

	/** Draws a small dot to the top-right of the badge. */
	@Prop({ reflect: true }) dot = false;

	/** Draws a square badge. */
	@Prop({ reflect: true }) square = false;

	/** The badge's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** Removes the extra anchored badge border for status icon usage where the asset already contains its own border. */
	@Prop({ reflect: true }) status = false;

	componentWillLoad() {
		this.syncSlotState();
	}

	private get slottedChildren(): HTMLElement[] {
		return Array.from(this.host.children).filter(
			(child): child is HTMLElement => child instanceof HTMLElement,
		);
	}

	// Anchored mode is enabled when `base` is present and there is either
	// explicit badge content or a dot badge that only needs the anchor element.
	private get isAnchored(): boolean {
		return this.hasBaseSlot && (this.hasBadgeSlot || this.dot);
	}

	private syncSlotState() {
		const baseSlotChildren = this.slottedChildren.filter(
			(child) => child.getAttribute("slot") === "base",
		);
		const badgeSlotChildren = this.slottedChildren.filter(
			(child) => child.getAttribute("slot") === "badge",
		);

		this.hasBaseSlot = baseSlotChildren.length > 0;
		this.hasBadgeSlot = badgeSlotChildren.length > 0;
	}

	private handleSlotChange = () => {
		this.syncSlotState();
	};

	render() {
		const { sentiment, size, pulse, disabled } = this;
		const cls = {
			badge: true,
			"badge--has-sentiment": !!sentiment,
			"badge--pill": this.pill,
			"badge--pulse": pulse,
			"badge--dot": this.dot,
			"badge--square": this.square,
			"badge--anchored": this.isAnchored,
			"badge--status": this.status,
			[`badge--${size}`]: true,
		};
		if (sentiment) {
			cls[`badge--${sentiment}`] = true;
		}
		if (disabled) {
			//for interactive badge
			cls["badge--disabled"] = true;
		}

		if (sentiment && this.host) {
			this.sheet.replaceSync(`
				:host {
					${getCssRulesForSentimentBadge({
						sentiment: this.sentiment,
						pulse: this.pulse,
					})}
				}
			`);
			addConstructedStyle(this.host.shadowRoot, this.sheet);
		}

		if (this.isAnchored) {
			return (
				<Host
					class={{
						"badge-host--anchored": true,
					}}
				>
					<slot name="base" onSlotchange={this.handleSlotChange} />
					<span
						ref={(el) => {
							this.badge = el;
						}}
						part="base indicator"
						class={cls}
						role="status"
					>
						<slot name="badge" onSlotchange={this.handleSlotChange} />
					</span>
				</Host>
			);
		}

		return (
			<Host>
				<span
					ref={(el) => {
						this.badge = el;
					}}
					part="base"
					class={cls}
					role="status"
				>
					<slot />
				</span>
			</Host>
		);
	}
}
