import {
	Component,
	Element,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { addConstructedStyle } from "../../utils/browser";

type HighlightRegistry = {
	delete: (name: string) => void;
	set: (name: string, highlight: unknown) => void;
};

type HighlightConstructor = new (...highlightRanges: Range[]) => unknown;

type CSSWithHighlights = typeof CSS & {
	highlights?: HighlightRegistry;
};

type WindowWithHighlight = Window & {
	Highlight?: HighlightConstructor;
};

/**
 * @part base - The component's internal wrapper.
 * @part highlight - Matching text to be highlighted (bold by default). If using a background color instead, ensure background color:text color ratio has contrast requirement of 4.5:1 to meet accessibility standards. You can verify with this tool https://www.tpgi.com/color-contrast-checker/
 *
 * @slot - The text to be highlighted, it's using CSS Custom Highlight API when default slot is provided, otherwise it falls back to a legacy implementation that wraps matched text with a span. https://caniuse.com/?search=css-highlight
 *
 * @data-testid highlighted-text - The highlighted text.
 * @data-testid text - The original text.
 */
@Component({
	tag: "hbr-highlight",
	styleUrl: "highlight.scss",
	shadow: true,
})
export class HbrHighlight {
	sheet: CSSStyleSheet = new CSSStyleSheet();
	@Element() host: HTMLHbrHighlightElement;

	/** Text containing the substring(s), instead of using the text prop, using the default slot for the CSS Custom Highlight API, since 2.19.0 */
	@Prop() text = "";

	/** Terms to highlight. */
	@Prop() queryText = "";

	/** Whether to differentiate between upper and lower case as distinct (true) or equivalent (false). Default is false. */
	@Prop() caseSensitive = false;

	/** Whether to treat queryText as an exact match (true), or to treat each term in the queryText as separate terms which will all be highlighted irrespective of order (false). Default is true. */
	@Prop() continuous = true;

	/**
	 * Variant of the highlight.
	 * */
	@Prop({ reflect: true }) variant: "underline";

	@State() slotText = "";

	private static instanceCounter = 0;
	private highlightName = `hbr-highlight-${++HbrHighlight.instanceCounter}`;
	private slotElement?: HTMLSlotElement;
	private textNode: Text | null = null;

	/** Returns an original text. */
	@Method()
	async getText() {
		return this.text;
	}

	private escapeRegExp(str: string) {
		return str.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, "\\$&");
	}

	private getHighlightRegistry(): HighlightRegistry | undefined {
		if (typeof CSS === "undefined") return undefined;
		return (CSS as CSSWithHighlights).highlights;
	}

	private getHighlightConstructor(): HighlightConstructor | undefined {
		if (typeof window === "undefined") return undefined;
		return (window as WindowWithHighlight).Highlight;
	}

	private isSupported(): boolean {
		return (
			typeof this.getHighlightRegistry() !== "undefined" &&
			typeof this.getHighlightConstructor() !== "undefined" &&
			typeof Range !== "undefined"
		);
	}

	private legacyHighlight() {
		let content = [this.text];
		let keywords: string[];
		if (this.queryText?.length > 0 && this.text?.length > 0) {
			const escapedQueryText = this.escapeRegExp(this.queryText);
			if (this.continuous) {
				keywords = [
					this.caseSensitive
						? escapedQueryText
						: escapedQueryText.toLowerCase(),
				];
			} else {
				const keywordsString = this.caseSensitive
					? this.queryText.trim()
					: this.queryText.trim().toLowerCase();
				keywords = keywordsString
					.split(/\s+/)
					.map((word) => this.escapeRegExp(word)); // Escaping special characters
			}

			const pattern = new RegExp(`(${keywords.join("|")})`, "g");
			let match = pattern.exec(
				this.caseSensitive ? this.text : this.text.toLowerCase(),
			);
			const indices = [];

			while (match !== null) {
				indices.push([match.index, match[0].length]);
				match = pattern.exec(
					this.caseSensitive ? this.text : this.text.toLowerCase(),
				);
			}

			if (indices.length > 0) {
				let prevIdx = 0;
				let texts: Array<[string, "normal" | "highlight"]> = [];
				indices.forEach((value, _) => {
					const [valIdx, valLength] = value;
					texts = [
						...texts,
						[this.text.substring(prevIdx, valIdx), "normal"],
						[this.text.substring(valIdx, valIdx + valLength), "highlight"],
					];
					prevIdx = valIdx + valLength;
				});
				texts = [
					...texts,
					[this.text.substring(prevIdx, this.text.length), "normal"],
				];
				content = texts.map((v) => {
					if (!v[0]) return;
					if (v[1] !== "highlight") {
						return <span>{v[0]}</span>;
					}
					return (
						<span
							data-testid="highlighted-text"
							class="highlight--highlighted-text"
							part="highlight"
						>
							{v[0]}
						</span>
					);
				});
			}
		}
		return content;
	}

	private computeMatchIndices(): Array<[number, number]> {
		if (!(this.queryText?.length > 0 && this.slotText?.length > 0)) return [];

		const escapedQueryText = this.escapeRegExp(this.queryText);
		let keywords: string[];
		if (this.continuous) {
			keywords = [
				this.caseSensitive ? escapedQueryText : escapedQueryText.toLowerCase(),
			];
		} else {
			const keywordsString = this.caseSensitive
				? this.queryText.trim()
				: this.queryText.trim().toLowerCase();
			keywords = keywordsString
				.split(/\s+/)
				.map((word) => this.escapeRegExp(word));
		}

		const pattern = new RegExp(`(${keywords.join("|")})`, "g");
		const haystack = this.caseSensitive
			? this.slotText
			: this.slotText.toLowerCase();
		const indices: Array<[number, number]> = [];
		let match = pattern.exec(haystack);
		while (match !== null) {
			indices.push([match.index, match[0].length]);
			match = pattern.exec(haystack);
		}
		return indices;
	}

	private clearHighlight() {
		this.getHighlightRegistry()?.delete(this.highlightName);
	}

	private syncSlotText() {
		if (this.text) return;

		const assigned = this.slotElement?.assignedNodes({ flatten: true }) ?? [];
		const textNode =
			assigned.find((node): node is Text => node.nodeType === Node.TEXT_NODE) ??
			null;
		const nextSlotText = textNode?.data || "";
		if (this.slotText !== nextSlotText) {
			this.slotText = nextSlotText;
		}
	}

	private applyHighlight() {
		const textNode = this.textNode;
		if (this.text || !this.isSupported() || !textNode) {
			this.clearHighlight();
			return;
		}

		this.clearHighlight();

		const indices = this.computeMatchIndices();
		if (indices.length === 0) return;

		const HighlightCtor = this.getHighlightConstructor();
		const highlights = this.getHighlightRegistry();
		if (!HighlightCtor || !highlights) return;

		const ranges = indices.map(([start, length]) => {
			const range = new Range();
			range.setStart(textNode, start);
			range.setEnd(textNode, start + length);
			return range;
		});

		highlights.set(this.highlightName, new HighlightCtor(...ranges));
	}

	componentDidLoad() {
		this.syncSlotText();
		this.applyHighlight();
	}

	componentDidUpdate() {
		this.applyHighlight();
	}

	disconnectedCallback() {
		this.clearHighlight();
	}

	@Watch("text")
	@Watch("queryText")
	@Watch("caseSensitive")
	@Watch("continuous")
	onInputsChanged() {
		this.applyHighlight();
	}

	render() {
		if (this.host && !this.text) {
			const underlineRule =
				this.variant === "underline" ? "text-decoration-line: underline;" : "";
			const rule = `
				 :host {
						::highlight(${this.highlightName}){
              color: var(--color);
              background: var(--bg);
              font-weight: var(--font-weight);
              text-decoration-color: var(--text-decoration-color);
              text-decoration-thickness: var(--text-decoration-thickness);
              text-underline-offset: var(--text-underline-offset);
              ${underlineRule}
            }
				 }
			 `;
			this.sheet.replaceSync(rule);
			addConstructedStyle(this.host.shadowRoot, this.sheet);
		}
		let content = null;
		if (this.text) {
			content = this.legacyHighlight();
		}
		return (
			<Host data-name={this.highlightName}>
				{!this.text && (
					<span style={{ display: "none" }} aria-hidden="true">
						<slot
							ref={(el) => {
								this.slotElement = el as HTMLSlotElement | undefined;
							}}
							onSlotchange={() => {
								this.syncSlotText();
							}}
						/>
					</span>
				)}
				<span
					data-testid="text"
					class={{
						highlight: true,
						"highlight--underline": this.variant === "underline",
					}}
					part="base"
					ref={(el) => {
						if (this.text) return;
						if (!el) {
							this.textNode = null;
							return;
						}
						if (
							el.childNodes.length === 1 &&
							el.firstChild?.nodeType === Node.TEXT_NODE
						) {
							(el.firstChild as Text).data = this.slotText;
						} else {
							el.textContent = this.slotText;
						}
						this.textNode = el.firstChild as Text;
					}}
				>
					{this.text ? content : this.slotText}
				</span>
			</Host>
		);
	}
}
